    m.remove();
    if (!list.length) { toast('Nothing visible to export', true); return; }
    const base = (list.length === 1 ? list[0].name : 'sculpt').replace(/[^\\w\\- ]+/g, '').trim().replace(/\\s+/g, '-') || 'sculpt';
    const bytes = f === 'stl' ? buildSTL(list) : buildOBJ(list);
